<script setup lang="ts">
import { ref } from "vue";
import { ElMessage, ElMessageBox } from "element-plus";
defineI18nRoute(false); definePageMeta({ layout: "admin-taiko", middleware: "admin-auth" }); useHead({ title: "年度报告" });
const apiFetch = useAdminApiFetch(); const query = ref(""); const loading = ref(false); const items = ref<any[]>([]);
const search = async () => { loading.value = true; try { items.value = (await apiFetch<{ items: any[] }>("/api/admin/annual-summaries", { query: { q: query.value } })).items; } catch (e:any) { ElMessage.error(e?.data?.statusMessage || "查询失败"); } finally { loading.value = false; } };
const remove = async (item:any) => { try { await ElMessageBox.confirm(`确定删除 ${item.nickname || item.taikoId} 的年度报告吗？此操作不可撤销。`, "删除确认", { type: "warning" }); await apiFetch(`/api/admin/annual-summaries/${encodeURIComponent(item.id)}`, { method: "DELETE" }); ElMessage.success("年度报告已删除"); await search(); } catch (e:any) { if (e === "cancel" || e === "close") return; ElMessage.error(e?.data?.statusMessage || "删除失败"); } };
</script>
<template><div class="admin-page-stack"><div class="page-heading"><div><span class="eyebrow">Annual reports</span><h2>年度报告管理</h2><p>临时权限：按账号、太鼓 ID 或昵称查找报告，并在确认后删除缓存。</p></div></div><el-card><div class="search"><el-input v-model="query" placeholder="输入用户 ID 或昵称" clearable @keyup.enter="search" /><el-button type="primary" :loading="loading" @click="search">查询</el-button></div><el-table v-if="items.length" :data="items" stripe><el-table-column prop="nickname" label="昵称"/><el-table-column prop="taikoId" label="太鼓 ID"/><el-table-column prop="id" label="报告 ID" min-width="250"/><el-table-column prop="generatedAt" label="生成时间"/><el-table-column label="操作" width="180"><template #default="{ row }"><el-button link type="primary" @click="navigateTo(`/admin/taiko/annual-summaries/${encodeURIComponent(row.id)}`)">查看</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><el-empty v-else description="暂无结果" /></el-card></div></template>
<style scoped>.admin-page-stack{display:grid;gap:20px}.page-heading h2{margin:6px 0;font-size:30px}.page-heading p{margin:0;color:#6b7280}.eyebrow{color:#8f6d3f;font-size:12px;letter-spacing:.14em;text-transform:uppercase}.search{display:flex;gap:10px;margin-bottom:18px}.search .el-input{max-width:420px}</style>
